"use client";

import { useEffect, useState, type FormEvent, type ReactNode } from "react";
import { BookOpen, Check, ChevronLeft, GraduationCap, LockKeyhole, Mail, Pencil, Plus, UserRound, UsersRound, X } from "lucide-react";
import type { Assignment, Completion, Dataset, Expense, Group, Payment, Student } from "@/lib/types";
import { categories, completionLabels, currentMonth, days, formatDate, formatMoney, paidFor, studentBalance, today } from "@/lib/types";

export type ModalState =
  | { type: "login" } | { type: "student"; item?: Student } | { type: "group"; item?: Group }
  | { type: "attendance"; groupId?: number; lessonDate?: string } | { type: "payment"; studentId?: number; groupId?: number; item?: Payment }
  | { type: "expense"; item?: Expense } | { type: "assignment"; groupId?: number; item?: Assignment }
  | { type: "progress"; assignmentId: number } | { type: "profile"; studentId: number } | { type: "password" };

type Props = { modal: ModalState; data: Dataset; month: string; busy: boolean; demoCredentials: boolean; onClose: () => void; onOpen: (modal: ModalState, protect?: boolean) => void; onAction: (action: string, payload: Record<string, unknown>) => Promise<boolean>; onLogin: (username: string, password: string) => Promise<string | null>; onPassword: (oldPassword: string, newPassword: string) => Promise<string | null> };

function Dialog({ title, subtitle, children, onClose, wide = false }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  useEffect(() => { const fn = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); }; window.addEventListener("keydown", fn); return () => window.removeEventListener("keydown", fn); }, [onClose]);
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section className={`modal ${wide ? "modal-wide" : ""}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-header"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button type="button" className="icon-button" onClick={onClose} aria-label="إغلاق"><X size={19}/></button></div><div className="modal-body">{children}</div></section></div>;
}
const Field = ({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) => <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>;
function Actions({ busy, onClose, label = "حفظ البيانات" }: { busy: boolean; onClose: () => void; label?: string }) { return <div className="form-actions"><button type="button" className="button button-light" onClick={onClose}>إلغاء</button><button className="button button-primary" type="submit" disabled={busy}>{busy ? "جارٍ الحفظ..." : label}</button></div>; }
const val = (f: FormData, key: string) => String(f.get(key) || "");

function LoginForm({ onLogin, busy, demoCredentials }: Pick<Props, "onLogin" | "busy" | "demoCredentials">) {
  const [error, setError] = useState("");
  return <form onSubmit={async e => { e.preventDefault(); setError(""); const f = new FormData(e.currentTarget); const result = await onLogin(val(f, "username"), val(f, "password")); if (result) setError(result); }} className="form-stack">
    <div className="login-intro"><div className="login-icon"><LockKeyhole size={22}/></div><div><strong>مرحباً بعودتك!</strong><p>سجّل الدخول للوصول إلى بياناتك وإدارتها بأمان.</p></div></div>
    {demoCredentials && <div className="demo-credentials"><strong>بيانات الدخول التجريبية</strong><span dir="ltr">mikhail &nbsp; / &nbsp; Teacher@2026</span><small>غيّر كلمة المرور من الإعدادات بعد الدخول.</small></div>}
    <Field label="اسم المستخدم"><input name="username" autoComplete="username" required defaultValue={demoCredentials ? "mikhail" : ""} placeholder="اسم المستخدم"/></Field>
    <Field label="كلمة المرور"><input name="password" type="password" autoComplete="current-password" required placeholder="أدخل كلمة المرور"/></Field>
    {error && <div className="form-error">{error}</div>}<button className="button button-primary button-block" disabled={busy}>{busy ? "جارٍ تسجيل الدخول..." : "تسجيل الدخول"}<ChevronLeft size={16}/></button>
  </form>;
}

function StudentForm({ item, data, busy, onAction, onClose }: { item?: Student; data: Dataset; busy: boolean; onAction: Props["onAction"]; onClose: () => void }) {
  const [selected, setSelected] = useState<number[]>(data.memberships.filter(m => m.studentId === item?.id).map(m => m.groupId));
  const [fee, setFee] = useState(item?.monthlyFee ?? 0);
  return <form className="form-stack" onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); if (await onAction("saveStudent", { id: item?.id, name: val(f,"name"), grade: val(f,"grade"), phone: val(f,"phone"), monthlyFee: fee, notes: val(f,"notes"), groupIds: selected })) onClose(); }}>
    <div className="form-grid"><Field label="اسم الطالب بالكامل *"><input name="name" defaultValue={item?.name} required minLength={3} maxLength={120} placeholder="مثال: أحمد محمد علي"/></Field><Field label="الصف الدراسي *"><input name="grade" defaultValue={item?.grade} required maxLength={80} placeholder="مثال: الأول الثانوي"/></Field><Field label="رقم الهاتف"><input name="phone" dir="ltr" defaultValue={item?.phone} maxLength={30} placeholder="01xxxxxxxxx"/></Field><Field label="الاشتراك الشهري (ج.م) *"><input type="number" min="0" max="10000000" required value={fee} onChange={e => setFee(Number(e.target.value))}/></Field></div>
    <div className="field"><span>المجموعات <small>يمكن اختيار أكثر من مجموعة</small></span><div className="check-grid">{data.groups.length ? data.groups.map(g => <label className={`check-option ${selected.includes(g.id) ? "checked" : ""}`} key={g.id}><input type="checkbox" checked={selected.includes(g.id)} onChange={() => { const next = selected.includes(g.id) ? selected.filter(x => x !== g.id) : [...selected, g.id]; setSelected(next); if (!item && next.length === 1) setFee(g.monthlyFee); }}/><span>{g.name}<small>{g.subject}</small></span></label>) : <p className="muted">أضف مجموعة أولاً من صفحة المجموعات.</p>}</div><small>عند اختيار مجموعة واحدة يطبق اشتراك الطالب، وللمجموعات المتعددة يطبق اشتراك كل مجموعة.</small></div>
    <Field label="ملاحظات المعلم"><textarea name="notes" rows={3} defaultValue={item?.notes} maxLength={2000} placeholder="أضف أي ملاحظات مهمة عن الطالب..."/></Field><Actions busy={busy} onClose={onClose}/>
  </form>;
}
function GroupForm({ item, data, busy, onAction, onClose }: { item?: Group; data: Dataset; busy: boolean; onAction: Props["onAction"]; onClose: () => void }) {
  const [selected, setSelected] = useState(data.memberships.filter(m => m.groupId === item?.id).map(m => m.studentId));
  const [search, setSearch] = useState("");
  return <form className="form-stack" onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); if (await onAction("saveGroup", { id: item?.id, name: val(f,"name"), grade: val(f,"grade"), subject: val(f,"subject"), day: Number(val(f,"day")), time: val(f,"time"), duration: Number(val(f,"duration")), monthlyFee: Number(val(f,"monthlyFee")), color: item?.color || "blue", studentIds: selected })) onClose(); }}>
    <div className="form-grid"><Field label="اسم المجموعة *"><input name="name" defaultValue={item?.name} required maxLength={120} placeholder="مثال: مجموعة الأول الثانوي"/></Field><Field label="الصف الدراسي *"><input name="grade" defaultValue={item?.grade} required placeholder="مثال: الأول الثانوي"/></Field><Field label="المادة *"><input name="subject" defaultValue={item?.subject || "اللغة العربية"} required/></Field><Field label="الاشتراك الشهري (ج.م) *"><input type="number" name="monthlyFee" min="0" required defaultValue={item?.monthlyFee ?? 350}/></Field><Field label="يوم الحصة"><select name="day" defaultValue={item?.day ?? new Date().getDay()}>{days.map((d,i) => <option key={d} value={i}>{d}</option>)}</select></Field><Field label="وقت الحصة"><input name="time" type="time" required defaultValue={item?.time || "14:00"}/></Field><Field label="مدة الحصة بالدقائق"><input name="duration" type="number" min="15" max="480" required defaultValue={item?.duration || 90}/></Field></div>
    <div className="field"><span>طلاب المجموعة <small>({selected.length} محدد)</small></span><input value={search} onChange={e => setSearch(e.target.value)} placeholder="ابحث عن طالب..."/><div className="check-grid scroll-check">{data.students.filter(s => s.name.includes(search)).map(s => <label className={`check-option ${selected.includes(s.id) ? "checked" : ""}`} key={s.id}><input type="checkbox" checked={selected.includes(s.id)} onChange={() => setSelected(selected.includes(s.id) ? selected.filter(x => x !== s.id) : [...selected, s.id])}/><span>{s.name}<small>{s.grade}</small></span></label>)}{!data.students.length && <p className="muted">لا يوجد طلاب بعد.</p>}</div></div><Actions busy={busy} onClose={onClose}/>
  </form>;
}
function AttendanceForm({ groupId: initialGroup, lessonDate: initialDate, data, busy, onAction, onClose }: { groupId?: number; lessonDate?: string; data: Dataset; busy: boolean; onAction: Props["onAction"]; onClose: () => void }) {
  const [groupId, setGroupId] = useState(initialGroup || data.groups[0]?.id || 0); const [lessonDate, setDate] = useState(initialDate || today());
  const [states, setStates] = useState<Record<number, "present" | "absent">>({});
  const members = data.memberships.filter(m => m.groupId === groupId).map(m => data.students.find(s => s.id === m.studentId)).filter((s): s is Student => !!s);
  useEffect(() => { const map: Record<number, "present" | "absent"> = {}; data.memberships.filter(m => m.groupId === groupId).forEach(m => { map[m.studentId] = data.attendance.find(a => a.groupId === groupId && a.studentId === m.studentId && a.lessonDate === lessonDate)?.status || "present"; }); setStates(map); }, [data, groupId, lessonDate]);
  return <form className="form-stack" onSubmit={async e => { e.preventDefault(); if (await onAction("saveAttendance", { groupId, lessonDate, records: members.map(s => ({ studentId: s.id, status: states[s.id] || "present" })) })) onClose(); }}>
    <div className="form-grid"><Field label="المجموعة"><select value={groupId} onChange={e => setGroupId(Number(e.target.value))} required><option value={0} disabled>اختر المجموعة</option>{data.groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select></Field><Field label="تاريخ الحصة"><input type="date" value={lessonDate} onChange={e => setDate(e.target.value)} required/></Field></div>
    <div className="attendance-head"><span>الطلاب ({members.length})</span><button type="button" className="text-link" onClick={() => setStates(Object.fromEntries(members.map(s => [s.id, "present"]))) }>تحديد الكل حاضر</button></div><div className="attendance-list">{members.map(s => <div className="attendance-row" key={s.id}><div className="person-cell"><span className="avatar avatar-sm">{s.name.slice(0,1)}</span><strong>{s.name}</strong></div><div className="segmented"><button type="button" className={states[s.id] === "present" ? "is-present" : ""} onClick={() => setStates({ ...states, [s.id]: "present" })}>حاضر</button><button type="button" className={states[s.id] === "absent" ? "is-absent" : ""} onClick={() => setStates({ ...states, [s.id]: "absent" })}>غائب</button></div></div>)}{!members.length && <div className="empty-inline">لا يوجد طلاب في هذه المجموعة بعد.</div>}</div><Actions busy={busy || !members.length} onClose={onClose} label="حفظ الحضور"/>
  </form>;
}
function PaymentForm({ item, studentId: initialStudent, groupId: initialGroup, initialMonth, data, busy, onAction, onClose }: { item?: Payment; studentId?: number; groupId?: number; initialMonth: string; data: Dataset; busy: boolean; onAction: Props["onAction"]; onClose: () => void }) {
  const [studentId, setStudent] = useState(item?.studentId || initialStudent || (initialGroup ? data.memberships.find(m => m.groupId === initialGroup)?.studentId : undefined) || data.students[0]?.id || 0);
  const studentGroups = data.memberships.filter(m => m.studentId === studentId);
  const [groupId, setGroup] = useState(item?.groupId || initialGroup || studentGroups[0]?.groupId || 0);
  const [month, setMonth] = useState(item?.month || initialMonth);
  const member = studentGroups.find(m => m.groupId === groupId);
  const already = member ? paidFor(data, studentId, groupId, month) : 0;
  const credit = item && item.studentId === studentId && item.groupId === groupId && item.month === month ? item.amount : 0;
  const remaining = Math.max(0, (member?.fee || 0) - already + credit);
  return <form className="form-stack" onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); if (await onAction("savePayment", { id: item?.id, studentId, groupId, amount: Number(val(f,"amount")), paymentDate: val(f,"paymentDate"), month, notes: val(f,"notes") })) onClose(); }}>
    <div className="form-grid"><Field label="الطالب"><select value={studentId} required onChange={e => { const next = Number(e.target.value); setStudent(next); setGroup(data.memberships.find(m => m.studentId === next)?.groupId || 0); }}><option value={0} disabled>اختر الطالب</option>{data.students.map(s => <option value={s.id} key={s.id}>{s.name}</option>)}</select></Field><Field label="المجموعة"><select value={groupId} required onChange={e => setGroup(Number(e.target.value))}><option value={0} disabled>اختر المجموعة</option>{studentGroups.map(m => <option value={m.groupId} key={m.id}>{data.groups.find(g => g.id === m.groupId)?.name}</option>)}</select></Field><Field label="شهر الاشتراك"><input type="month" required value={month} onChange={e => setMonth(e.target.value)}/></Field><Field label="تاريخ الدفع"><input type="date" name="paymentDate" required defaultValue={item?.paymentDate || today()}/></Field><Field label="المبلغ المدفوع (ج.م)"><input key={`${studentId}-${groupId}-${month}`} type="number" name="amount" min="1" max={remaining} required defaultValue={item?.amount || remaining || ""} placeholder="المبلغ"/></Field></div>
    <div className="info-box"><span>قيمة الاشتراك: <b>{formatMoney(member?.fee || 0)} ج.م</b></span><span>المتبقي لهذا الشهر: <b>{formatMoney(remaining)} ج.م</b></span></div>{!member && <div className="form-error">أضف الطالب إلى مجموعة أولاً.</div>}
    <Field label="ملاحظات"><input name="notes" defaultValue={item?.notes} maxLength={500} placeholder="ملاحظات اختيارية"/></Field><Actions busy={busy || !member || remaining <= 0} onClose={onClose} label="حفظ الدفعة"/>
  </form>;
}
function ExpenseForm({ item, busy, onAction, onClose }: { item?: Expense; busy: boolean; onAction: Props["onAction"]; onClose: () => void }) {
  return <form className="form-stack" onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); if (await onAction("saveExpense", { id: item?.id, description: val(f,"description"), category: val(f,"category"), amount: Number(val(f,"amount")), expenseDate: val(f,"expenseDate") })) onClose(); }}>
    <Field label="وصف المصروف"><input name="description" required defaultValue={item?.description} placeholder="مثال: طباعة مذكرات الطلاب"/></Field><div className="form-grid"><Field label="التصنيف"><select name="category" defaultValue={item?.category || categories[0]}>{categories.map(c => <option key={c}>{c}</option>)}</select></Field><Field label="المبلغ (ج.م)"><input name="amount" type="number" min="1" required defaultValue={item?.amount} placeholder="0"/></Field><Field label="التاريخ"><input name="expenseDate" type="date" required defaultValue={item?.expenseDate || today()}/></Field></div><Actions busy={busy} onClose={onClose} label="حفظ المصروف"/>
  </form>;
}
function AssignmentForm({ item, groupId, data, busy, onAction, onClose }: { item?: Assignment; groupId?: number; data: Dataset; busy: boolean; onAction: Props["onAction"]; onClose: () => void }) {
  return <form className="form-stack" onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); if (await onAction("saveAssignment", { id: item?.id, groupId: Number(item?.groupId || val(f,"groupId")), lessonDate: val(f,"lessonDate"), homework: val(f,"homework"), memorization: val(f,"memorization") })) onClose(); }}>
    <div className="form-grid"><Field label="المجموعة"><select name="groupId" required defaultValue={item?.groupId || groupId || data.groups[0]?.id} disabled={!!item}>{data.groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select></Field><Field label="تاريخ الحصة"><input name="lessonDate" type="date" required defaultValue={item?.lessonDate || today()}/></Field></div><Field label="الواجب المطلوب"><textarea name="homework" rows={4} defaultValue={item?.homework} placeholder="اكتب الواجب المطلوب لهذه الحصة..."/></Field><Field label="الحفظ المطلوب"><textarea name="memorization" rows={3} defaultValue={item?.memorization} placeholder="اكتب المطلوب حفظه..."/></Field><Actions busy={busy || !data.groups.length} onClose={onClose} label="حفظ الواجب"/>
  </form>;
}
function ProgressForm({ assignmentId, data, busy, onAction, onClose }: { assignmentId: number; data: Dataset; busy: boolean; onAction: Props["onAction"]; onClose: () => void }) {
  const assignment = data.assignments.find(a => a.id === assignmentId);
  const members = data.memberships.filter(m => m.groupId === assignment?.groupId).map(m => data.students.find(s => s.id === m.studentId)).filter((s): s is Student => !!s);
  const [states, setStates] = useState<Record<number, { homeworkStatus: Completion; memorizationStatus: Completion }>>(() => Object.fromEntries(members.map(s => { const p = data.progress.find(p => p.assignmentId === assignmentId && p.studentId === s.id); return [s.id, { homeworkStatus: p?.homeworkStatus || "not_completed", memorizationStatus: p?.memorizationStatus || "not_completed" }]; })));
  return <form className="form-stack" onSubmit={async e => { e.preventDefault(); if (await onAction("saveProgress", { assignmentId, records: members.map(s => ({ studentId: s.id, ...states[s.id] })) })) onClose(); }}><div className="info-box"><span><BookOpen size={16}/> {assignment?.homework || "لا يوجد واجب"}</span><span>{formatDate(assignment?.lessonDate || "")}</span></div><div className="progress-table"><div className="progress-header"><span>الطالب</span><span>الواجب</span><span>الحفظ</span></div>{members.map(s => <div className="progress-row" key={s.id}><strong>{s.name}</strong>{(["homeworkStatus", "memorizationStatus"] as const).map(key => <select aria-label={`${key === "homeworkStatus" ? "الواجب" : "الحفظ"} - ${s.name}`} key={key} value={states[s.id]?.[key]} onChange={e => setStates({ ...states, [s.id]: { ...states[s.id], [key]: e.target.value as Completion } })}>{Object.entries(completionLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select>)}</div>)}{!members.length && <div className="empty-inline">لا يوجد طلاب في هذه المجموعة.</div>}</div><Actions busy={busy || !members.length} onClose={onClose} label="حفظ المتابعة"/></form>;
}
function StudentProfile({ studentId, data, onOpen }: { studentId: number; data: Dataset; onOpen: Props["onOpen"] }) {
  const s = data.students.find(s => s.id === studentId); if (!s) return <div className="empty-inline">الطالب غير موجود.</div>;
  const memberships = data.memberships.filter(m => m.studentId === s.id); const records = data.attendance.filter(a => a.studentId === s.id); const present = records.filter(a => a.status === "present").length; const absent = records.length - present; const percent = records.length ? Math.round(present / records.length * 100) : 0;
  const balance = studentBalance(data, s.id, currentMonth()); const payments = data.payments.filter(p => p.studentId === s.id).sort((a,b) => b.paymentDate.localeCompare(a.paymentDate)); const progress = data.progress.filter(p => p.studentId === s.id).sort((a,b) => (data.assignments.find(x => x.id === b.assignmentId)?.lessonDate || "").localeCompare(data.assignments.find(x => x.id === a.assignmentId)?.lessonDate || ""));
  return <div className="profile"><div className="profile-top"><span className="avatar avatar-xl">{s.name.slice(0,1)}</span><div><h3>{s.name}</h3><p>{s.grade} {s.phone ? ` · ${s.phone}` : ""}</p><div className="tag-list">{memberships.map(m => <span className="tag" key={m.id}>{data.groups.find(g => g.id === m.groupId)?.name}</span>)}{!memberships.length && <span className="tag">بدون مجموعة</span>}<span className={`status ${!balance.due ? "status-neutral" : balance.status === "paid" ? "status-paid" : balance.status === "partial" ? "status-partial" : "status-unpaid"}`}>{!balance.due ? "بدون اشتراك" : balance.status === "paid" ? "مدفوع هذا الشهر" : balance.status === "partial" ? "مدفوع جزئياً" : "غير مدفوع هذا الشهر"}</span></div></div><button className="button button-light button-small" onClick={() => onOpen({ type: "student", item: s }, true)}><Pencil size={14}/> تعديل</button></div>
    <div className="profile-stats"><div><span>نسبة الحضور</span><strong>{percent}%</strong></div><div><span>الحصص الحاضرة</span><strong>{present}</strong></div><div><span>الحصص الغائبة</span><strong>{absent}</strong></div><div><span>المتبقي هذا الشهر</span><strong>{formatMoney(balance.remaining)} <small>ج.م</small></strong></div></div>
    <div className="profile-section"><div className="section-line"><h4>سجل المدفوعات</h4><button className="text-link" onClick={() => onOpen({ type: "payment", studentId: s.id }, true)}><Plus size={14}/> تسجيل دفعة</button></div>{payments.length ? <div className="compact-table">{payments.map(p => <div key={p.id}><span>{data.groups.find(g => g.id === p.groupId)?.name || "مجموعة"}<small>{formatDate(p.paymentDate)} · {p.month}</small></span><b>{formatMoney(p.amount)} ج.م</b></div>)}</div> : <p className="muted">لا توجد دفعات مسجلة.</p>}</div>
    <div className="profile-section"><h4>متابعة الواجب والحفظ</h4>{progress.length ? <div className="compact-table">{progress.map(p => { const a = data.assignments.find(a => a.id === p.assignmentId); return <div key={p.id}><span>{data.groups.find(g => g.id === a?.groupId)?.name}<small>{formatDate(a?.lessonDate || "")}</small></span><span>الواجب: {completionLabels[p.homeworkStatus]} · الحفظ: {completionLabels[p.memorizationStatus]}</span></div>; })}</div> : <p className="muted">لا توجد متابعة مسجلة بعد.</p>}</div>
    <div className="profile-section"><h4>سجل الحضور</h4>{records.length ? <div className="compact-table">{records.sort((a,b) => b.lessonDate.localeCompare(a.lessonDate)).map(a => <div key={a.id}><span>{data.groups.find(g => g.id === a.groupId)?.name}<small>{formatDate(a.lessonDate)}</small></span><span className={`status ${a.status === "present" ? "status-paid" : "status-unpaid"}`}>{a.status === "present" ? "حاضر" : "غائب"}</span></div>)}</div> : <p className="muted">لا توجد سجلات حضور بعد.</p>}</div><div className="profile-section"><h4>ملاحظات المعلم</h4><p className="note-box">{s.notes || "لا توجد ملاحظات مضافة لهذا الطالب."}</p></div>
  </div>;
}
function PasswordForm({ busy, onPassword }: { busy: boolean; onPassword: Props["onPassword"] }) {
  const [error, setError] = useState(""); return <form className="form-stack" onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); if (val(f,"newPassword") !== val(f,"confirm")) { setError("كلمتا المرور غير متطابقتين"); return; } const result = await onPassword(val(f,"oldPassword"), val(f,"newPassword")); if (result) setError(result); }}><Field label="كلمة المرور الحالية"><input type="password" name="oldPassword" required autoComplete="current-password"/></Field><Field label="كلمة المرور الجديدة"><input type="password" name="newPassword" required minLength={10} autoComplete="new-password"/></Field><Field label="تأكيد كلمة المرور الجديدة"><input type="password" name="confirm" required minLength={10} autoComplete="new-password"/></Field>{error && <div className="form-error">{error}</div>}<button className="button button-primary" disabled={busy}>{busy ? "جارٍ الحفظ..." : "تحديث كلمة المرور"}</button><p className="muted">سيتم تسجيل خروج جميع الجلسات بعد تغيير كلمة المرور.</p></form>;
}

export function ModalRenderer(props: Props) {
  const { modal, data, month, onClose, onOpen, onAction, busy, onLogin, onPassword, demoCredentials } = props;
  if (modal.type === "login") return <Dialog title="تسجيل الدخول" subtitle="لوحة مستر ميخائيل توما" onClose={onClose}><LoginForm onLogin={onLogin} busy={busy} demoCredentials={demoCredentials}/></Dialog>;
  if (modal.type === "student") return <Dialog title={modal.item ? "تعديل بيانات الطالب" : "إضافة طالب جديد"} subtitle="احتفظ بكل بيانات الطالب في مكان واحد" wide onClose={onClose}><StudentForm item={modal.item} data={data} busy={busy} onAction={onAction} onClose={onClose}/></Dialog>;
  if (modal.type === "group") return <Dialog title={modal.item ? "تعديل المجموعة" : "إضافة مجموعة جديدة"} subtitle="نظّم الطلاب والحصص والاشتراك الشهري" wide onClose={onClose}><GroupForm item={modal.item} data={data} busy={busy} onAction={onAction} onClose={onClose}/></Dialog>;
  if (modal.type === "attendance") return <Dialog title="تسجيل الحضور والغياب" subtitle="يمكن تعديل سجل أي حصة باختيار تاريخها" wide onClose={onClose}><AttendanceForm groupId={modal.groupId} lessonDate={modal.lessonDate} data={data} busy={busy} onAction={onAction} onClose={onClose}/></Dialog>;
  if (modal.type === "payment") return <Dialog title={modal.item ? "تعديل الدفعة" : "تسجيل دفعة جديدة"} subtitle="يمكن تسجيل دفعات جزئية لكل مجموعة" onClose={onClose}><PaymentForm item={modal.item} studentId={modal.studentId} groupId={modal.groupId} initialMonth={month} data={data} busy={busy} onAction={onAction} onClose={onClose}/></Dialog>;
  if (modal.type === "expense") return <Dialog title={modal.item ? "تعديل المصروف" : "إضافة مصروف"} subtitle="سجّل مصروفاتك وتابع تفاصيلها" onClose={onClose}><ExpenseForm item={modal.item} busy={busy} onAction={onAction} onClose={onClose}/></Dialog>;
  if (modal.type === "assignment") return <Dialog title={modal.item ? "تعديل الواجب والحفظ" : "إضافة واجب وحفظ"} subtitle="لكل مجموعة سجل مستقل من الواجبات" onClose={onClose}><AssignmentForm item={modal.item} groupId={modal.groupId} data={data} busy={busy} onAction={onAction} onClose={onClose}/></Dialog>;
  if (modal.type === "progress") return <Dialog title="متابعة الواجب والحفظ" subtitle="سجّل مستوى إنجاز كل طالب" wide onClose={onClose}><ProgressForm assignmentId={modal.assignmentId} data={data} busy={busy} onAction={onAction} onClose={onClose}/></Dialog>;
  if (modal.type === "profile") return <Dialog title="ملف الطالب" subtitle="نظرة شاملة على بيانات الطالب وتقدمه" wide onClose={onClose}><StudentProfile studentId={modal.studentId} data={data} onOpen={onOpen}/></Dialog>;
  return <Dialog title="تغيير كلمة المرور" subtitle="احرص على استخدام كلمة مرور قوية وفريدة" onClose={onClose}><PasswordForm busy={busy} onPassword={onPassword}/></Dialog>;
}
